"""Turn raw benchmark results into a Markdown report, CSV tables and charts.

python -m analysis.report --results results --pricing configs/pricing.yaml --mode spot
"""

from __future__ import annotations

import argparse
import csv
import os
from collections import defaultdict

from analysis.costs import (
    PRICING_MODES,
    best_per_profile,
    inference_rows,
    is_synthetic,
    load_inference_runs,
    load_pricing,
    load_training_runs,
    recommend,
    training_rows,
)

SYNTHETIC_BANNER = (
    "> **WARNING: SYNTHETIC DEMO DATA.** These numbers were generated by `analysis.make_demo_data` "
    "to exercise the pipeline. They are not measurements and must not be reported as results.\n"
)


def fmt(value, digits=2) -> str:
    if value is None:
        return "-"
    if isinstance(value, float):
        if abs(value) >= 1000:
            return f"{value:,.0f}"
        return f"{value:.{digits}f}"
    return str(value)


def markdown_table(rows: list[dict], columns: list[tuple[str, str]]) -> str:
    header = "| " + " | ".join(title for _, title in columns) + " |"
    sep = "|" + "|".join("---" for _ in columns) + "|"
    body = ["| " + " | ".join(fmt(r.get(key)) for key, _ in columns) + " |" for r in rows]
    return "\n".join([header, sep, *body])


def write_csv(path: str, rows: list[dict]) -> None:
    if not rows:
        return
    with open(path, "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0].keys()))
        w.writeheader()
        w.writerows(rows)


def _by_profile(rows):
    groups = defaultdict(list)
    for r in rows:
        groups[r["accelerator_profile"]].append(r)
    return {k: sorted(v, key=lambda r: r["concurrency"]) for k, v in sorted(groups.items())}


def make_charts(train: list[dict], infer: list[dict], out_dir: str, synthetic: bool) -> list[str]:
    import matplotlib

    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    suffix = "  [SYNTHETIC DEMO DATA]" if synthetic else ""
    written = []

    def save(fig, name):
        path = os.path.join(out_dir, name)
        fig.tight_layout()
        fig.savefig(path, dpi=150)
        plt.close(fig)
        written.append(name)

    if infer:
        groups = _by_profile(infer)
        for key, ylabel, name, title in [
            ("output_tokens_per_s", "output tokens / s", "inference_throughput.png", "Throughput vs concurrency"),
            ("usd_per_million_output_tokens", "USD per 1M output tokens", "inference_cost.png",
             "Serving cost vs concurrency"),
            ("ttft_ms_p99", "p99 time to first token (ms)", "inference_ttft.png", "p99 TTFT vs concurrency"),
        ]:
            fig, ax = plt.subplots(figsize=(7, 4.2))
            for profile, rows in groups.items():
                ax.plot([r["concurrency"] for r in rows], [r[key] for r in rows], marker="o", label=profile)
            ax.set_xscale("log", base=2)
            ax.set_xlabel("concurrent requests")
            ax.set_ylabel(ylabel)
            ax.set_title(title + suffix)
            ax.grid(alpha=0.3)
            ax.legend()
            save(fig, name)

        fig, ax = plt.subplots(figsize=(7, 4.2))
        for profile, rows in groups.items():
            ax.plot([r["output_tokens_per_s"] for r in rows], [r["tpot_ms_p99"] for r in rows], marker="o",
                    label=profile)
        ax.set_xlabel("output tokens / s")
        ax.set_ylabel("p99 time per output token (ms)")
        ax.set_title("Latency-throughput frontier" + suffix)
        ax.grid(alpha=0.3)
        ax.legend()
        save(fig, "inference_frontier.png")

    if train:
        labels = [f"{r['accelerator_profile']}\n{r['padding']}" for r in train]
        fig, axes = plt.subplots(1, 3, figsize=(12, 4))
        for ax, key, title in [
            (axes[0], "tokens_per_s", "Training tokens / s"),
            (axes[1], "usd_per_million_tokens", "USD per 1M training tokens"),
            (axes[2], "mfu", "Model FLOPs utilization"),
        ]:
            ax.bar(labels, [r[key] or 0 for r in train])
            ax.set_title(title)
            ax.tick_params(axis="x", labelsize=8)
            ax.grid(axis="y", alpha=0.3)
        fig.suptitle("LoRA fine-tuning" + suffix)
        save(fig, "training.png")

    return written


def build_report(results_dir: str, pricing_path: str, mode: str, out_dir: str,
                 max_ttft_p99_ms: float, max_tpot_p99_ms: float) -> str:
    pricing = load_pricing(pricing_path)
    train_runs = load_training_runs(results_dir)
    infer_runs = load_inference_runs(results_dir)
    if not train_runs and not infer_runs:
        raise SystemExit(f"no results found under {results_dir}/training or {results_dir}/inference")
    synthetic = is_synthetic(train_runs, infer_runs)

    train = training_rows(train_runs, pricing, mode)
    infer = inference_rows(infer_runs, pricing, mode)
    os.makedirs(out_dir, exist_ok=True)
    write_csv(os.path.join(out_dir, "training.csv"), train)
    write_csv(os.path.join(out_dir, "inference.csv"), infer)
    charts = make_charts(train, infer, out_dir, synthetic)

    lines = ["# AccelBench report", ""]
    if synthetic:
        lines += [SYNTHETIC_BANNER, ""]
    lines += [f"Pricing mode: **{mode}** (from `{pricing_path}`; verify prices before publishing).", ""]

    if train:
        lines += ["## Fine-tuning (LoRA)", "", markdown_table(train, [
            ("accelerator_profile", "Profile"), ("padding", "Padding"), ("global_batch_size", "Global batch"),
            ("tokens_per_s", "Tokens/s"), ("tokens_per_s_per_device", "Tokens/s/chip"), ("mfu", "MFU"),
            ("first_step_s", "First step (s)"), ("xla_compilations", "XLA compiles"),
            ("usd_per_million_tokens", "$/1M tokens"), ("usd_per_run", "$/run"),
        ]), ""]

    if infer:
        lines += ["## Serving", "", markdown_table(infer, [
            ("accelerator_profile", "Profile"), ("concurrency", "Concurrency"),
            ("output_tokens_per_s", "Out tok/s"), ("ttft_ms_p50", "TTFT p50 (ms)"), ("ttft_ms_p99", "TTFT p99 (ms)"),
            ("tpot_ms_p99", "TPOT p99 (ms)"), ("e2e_s_p99", "E2E p99 (s)"), ("failed", "Failed"),
            ("usd_per_million_output_tokens", "$/1M out tokens"),
        ]), ""]

        feasible = recommend(infer, max_ttft_p99_ms=max_ttft_p99_ms, max_tpot_p99_ms=max_tpot_p99_ms)
        lines += [f"## Recommendation (SLA: p99 TTFT <= {max_ttft_p99_ms:g} ms, p99 TPOT <= {max_tpot_p99_ms:g} ms)",
                  ""]
        if feasible:
            top = feasible[0]
            lines += [
                f"Cheapest configuration meeting the SLA: **{top['accelerator_profile']}** at concurrency "
                f"{top['concurrency']}, {fmt(top['output_tokens_per_s'])} output tokens/s, "
                f"**${fmt(top['usd_per_million_output_tokens'], 3)} per 1M output tokens**.",
                "",
                markdown_table(best_per_profile(feasible), [
                    ("accelerator_profile", "Profile"), ("concurrency", "Best concurrency"),
                    ("output_tokens_per_s", "Out tok/s"), ("ttft_ms_p99", "TTFT p99 (ms)"),
                    ("usd_per_million_output_tokens", "$/1M out tokens"),
                ]),
                "",
            ]
        else:
            lines += ["No measured configuration meets this SLA.", ""]

    if charts:
        lines += ["## Charts", ""] + [f"![{c}]({c})" for c in charts] + [""]

    report = "\n".join(lines)
    with open(os.path.join(out_dir, "report.md"), "w") as f:
        f.write(report)
    return report


def main(argv=None):
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--results", default="results")
    p.add_argument("--pricing", default="configs/pricing.yaml")
    p.add_argument("--mode", choices=PRICING_MODES, default="spot")
    p.add_argument("--out", default=None, help="Defaults to <results>/report.")
    p.add_argument("--max-ttft-p99-ms", type=float, default=1000)
    p.add_argument("--max-tpot-p99-ms", type=float, default=100)
    args = p.parse_args(argv)
    out = args.out or os.path.join(args.results, "report")
    build_report(args.results, args.pricing, args.mode, out, args.max_ttft_p99_ms, args.max_tpot_p99_ms)
    print(f"report written to {os.path.join(out, 'report.md')}")


if __name__ == "__main__":
    main()
